public class TypeResolver {

    private static Map<Class<?>, Reference<Map<TypeVariable<?>, Type>>> typeVariableCache = new HashMap<>();
    private static boolean cacheEnabled = true;

    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
            for (int i = 0; i < actualTypeArguments.length; i++) {
                resolvedArguments[i] = resolveRawClass(actualTypeArguments[i], targetType);
            }
            return resolvedArguments;
        }
        return null;
    }

    private static Class<?> resolveRawClass(Type type, Class<?> targetType) {
        if (type instanceof Class) {
            return (Class<?>) type;
        } else if (type instanceof ParameterizedType) {
            return (Class<?>) ((ParameterizedType) type).getRawType();
        } else if (type instanceof TypeVariable) {
            Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(targetType);
            Type resolvedType = typeVariableMap.get(type);
            return resolvedType != null ? resolveRawClass(resolvedType, targetType) : null;
        }
        return null;
    }

    private static Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> targetType) {
        if (cacheEnabled && typeVariableCache.containsKey(targetType)) {
            return typeVariableCache.get(targetType).get();
        }
        Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
        Type genericSuperclass = targetType.getGenericSuperclass();
        if (genericSuperclass instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
            TypeVariable<?>[] typeParameters = targetType.getSuperclass().getTypeParameters();
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            for (int i = 0; i < typeParameters.length; i++) {
                typeVariableMap.put(typeParameters[i], actualTypeArguments[i]);
            }
        }
        typeVariableCache.put(targetType, new Reference<>(typeVariableMap));
        return typeVariableMap;

