static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    Calendar calendar = Calendar.getInstance();
    calendar.set(year, month - 1, day);

    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);
    int daysToSubtract = (dayOfWeek - Calendar.SUNDAY + dayStep) % 7;

    calendar.add(Calendar.DAY_OF_MONTH, -daysToSubtract);

    int newYear = calendar.get(Calendar.YEAR);
    int newMonth = calendar.get(Calendar.MONTH) + 1;
    int newDay = calendar.get(Calendar.DAY_OF_MONTH);

    return newYear * 10000 + newMonth * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
