        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (ch <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

