private int removeUnusedNodesHelper(CategoryNode node) {
    int removedCount = 0;
    List<CategoryNode> children = node.getChildren();
    Iterator<CategoryNode> iterator = children.iterator();
    while (iterator.hasNext()) {
        CategoryNode child = iterator.next();
        if (!child.isActive()) {
            iterator.remove();
            removedCount++;
        } else {
            removedCount += removeUnusedNodesHelper(child);
        }
    }
    return removedCount;
}

