public int readTag() throws IOException {
    if (pos == count) {
        fillBuf();
    }
    if (pos == count) {
        return 0; // EOF
    }
    int tag = 0;
    for (int shift = 0; shift < 32; shift += 7) {
        int b = buf[pos++];
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
    }
    throw new IOException("Invalid tag encountered");
}

